<script>const s=document.querySelector('#service'),b=document.querySelector('#barber'),d=document.querySelector('#date'),slot=document.querySelector('#slot');async function load(){if(!s.value||!b.value||!d.value)return;slot.disabled=true;slot.innerHTML='<option>Cargando horarios...</option>';const r=await fetch(`{{ route('slots') }}?barber_id=${b.value}&service_id=${s.value}&date=${d.value}`);const data=await r.json();slot.innerHTML=data.length?data.map(x=>`<option value="${x.start}">${x.start} - ${x.end}</option>`).join(''):'<option>No hay horarios disponibles</option>';slot.disabled=!data.length} [s,b,d].forEach(x=>x.addEventListener('change',load));</script>
